    op.execute("UPDATE cultural_traditions SET source_citation = COALESCE(source_citation, '[migrasi downgrade]'), approved_at = COALESCE(approved_at, now()) WHERE status = 'approved'")
    for t in ('cultural_traditions', 'movements', 'partners'):
        op.drop_constraint(f'fk_{t}_approved_by_user', t, type_='foreignkey')
        op.drop_constraint(f'fk_{t}_created_by_user', t, type_='foreignkey')
        op.drop_index(op.f(f'ix_{t}_status'), table_name=t)
        for c in ('deleted_at', 'published_at', 'approval_evidence_ref', 'approved_by_user_id',
                  'created_by_user_id', 'review_note', 'source_url'):
            op.drop_column(t, c)
    op.drop_index(op.f('ix_movements_tradition_id'), table_name='movements')
    op.drop_column('movements', 'approved_at')
    op.drop_column('partners', 'approved_at')
    op.drop_column('movements', 'source_citation')
    op.drop_column('partners', 'source_citation')
    op.drop_column('partners', 'status')
    op.create_check_constraint('ck_traditions_status', 'cultural_traditions', f"status IN ({sts_old})")
    op.create_check_constraint('ck_traditions_approved_has_provenance', 'cultural_traditions',
        "status <> 'approved' OR (source_citation IS NOT NULL AND approved_at IS NOT NULL)")
    op.create_check_constraint('ck_movements_status', 'movements', f"status IN ({sts_old})")
    op.create_check_constraint('ck_movements_assessment_requires_safe_approved', 'movements',
        "NOT assessment_enabled OR (practice_mode = 'solo_beginner' AND status = 'approved')")
    op.drop_constraint('ck_users_role', 'users', type_='check')
    op.execute("""UPDATE users SET role = CASE role WHEN 'admin' THEN 'platform_admin'
        WHEN 'curator' THEN 'content_editor' ELSE role END""")
    op.create_check_constraint('ck_users_role', 'users',
        "role IN ('learner','instructor','partner_admin','content_editor','platform_admin')")
    op.drop_column('users', 'locked_until')
    op.drop_column('users', 'failed_logins')

